$(function(){
  $("a").each(function (index, element){
   var href = $(this).attr("href");
   $(this).attr("data-href", href);
   $(this).removeAttr("href");
   $(this).css({ cursor: 'pointer' });

 });
 $("a:not(.btn_ajax)").click(function(){
    let url = $(this).data("href");
    const patt = /^(http(s)?:)?\/\/(www\.)?uipa.or.kr/;
    url = url.replace(patt, '');
	if ( $(this).attr('target') == '_blank' ) {
		window.open(url);
	} else {
		location.href = url;
	};
 });
 $(".board_view .cont a").attr("target","_blank");


});

$(document).ready(function(){
	$(".top-sch-btn").on("click",function(){
		$(".total_sch_pop").fadeIn();
	});
	$(".total_sch_bg, .total_sch_close").on("click", function(){
		$(".total_sch_pop").fadeOut();
	});
});

